import time

class CircuitBreaker:
    def __init__(self, threshold=5, reset_after=30.0):
        self.threshold, self.reset_after = threshold, reset_after
        self.failures, self.opened_at = 0, None

    def call(self, fn, *args, **kwargs):
        if self.opened_at is not None:
            if time.monotonic() - self.opened_at < self.reset_after:
                raise RuntimeError("circuit open")  # 快速失败，不打下游
            self.opened_at = None                    # 半开：放行一次试探
        try:
            result = fn(*args, **kwargs)
        except Exception:
            self.failures += 1
            if self.failures >= self.threshold:
                self.opened_at = time.monotonic()    # 打开熔断
            raise
        self.failures = 0                            # 成功则复位
        return result

import json, random, time
import redis

r = redis.Redis()

def get_product(pid, load_from_db):
    key, lock = f"product:{pid}", f"lock:product:{pid}"
    for _ in range(50):
        cached = r.get(key)
        if cached is not None:
            return json.loads(cached)
        # 只有抢到锁的请求去查库，锁 10 秒自动过期防死锁
        if r.set(lock, "1", nx=True, ex=10):
            try:
                data = load_from_db(pid)
                ttl = 300 + random.randint(0, 60)   # TTL 加抖动，错开过期
                r.set(key, json.dumps(data), ex=ttl)
                return data
            finally:
                r.delete(lock)
        time.sleep(0.05)                           # 没抢到锁：稍等再读缓存
    return load_from_db(pid)                       # 兜底

const http = require("node:http");

let shuttingDown = false;
const server = http.createServer((req, res) => {
  if (req.url === "/readyz") {
    res.writeHead(shuttingDown ? 503 : 200).end();  // 停机时就绪失败
    return;
  }
  setTimeout(() => res.end("ok"), 200);             // 模拟业务处理
});
server.listen(8080);

process.on("SIGTERM", () => {
  shuttingDown = true;
  // 停止接新连接，等在途请求结束后回调
  server.close(() => process.exit(0));
  server.closeIdleConnections();                    // 关闭空闲 keep-alive 连接
  // 兜底：宽限期前强制退出
  setTimeout(() => process.exit(1), 25_000).unref();
});

from flask import Flask, request, jsonify
import redis

app = Flask(__name__)
store = redis.Redis(host="redis", decode_responses=True)
# 反例：carts = {}  放在进程内存，换个实例就丢

@app.post("/cart/<user_id>/items")
def add_item(user_id):
    sku = request.json["sku"]
    key = f"cart:{user_id}"
    store.hincrby(key, sku, 1)       # 状态写到共享存储
    store.expire(key, 7 * 24 * 3600) # 购物车保留 7 天
    return jsonify(store.hgetall(key))

@app.get("/cart/<user_id>")
def get_cart(user_id):
    return jsonify(store.hgetall(f"cart:{user_id}"))

